import csv


def parse_border_crossings(csv_path: str) -> list[dict]:
    """
    Parserar en CSV-fil med gränspassagedata (Frontex) och returnerar
    en lista av dicts, en per rad. Antalsfält konverteras till int.
    """
    records = []
    with open(csv_path, newline="", encoding="utf-8-sig") as f:
        for row in csv.DictReader(f):
            # Rensa nycklar och värden från whitespace
            record = {k.strip(): v.strip() for k, v in row.items() if k}
            # Konvertera antal passager till int (hanterar även "1 234" / "1,234")
            for key in ("detections", "value", "count"):
                if key in record and record[key]:
                    try:
                        record[key] = int(float(record[key].replace(",", "").replace(" ", "")))
                    except ValueError:
                        pass
            # Hoppa över helt tomma rader
            if any(record.values()):
                records.append(record)
    return records
