import os
import stat


def audit_file_permissions(directory: str) -> list[dict]:
    """Granskar filrättigheter i en katalog och returnerar filer
    med för generösa behörigheter (world-writable, setuid, setgid)."""
    findings = []

    for root, _dirs, files in os.walk(directory):
        for name in files:
            path = os.path.join(root, name)
            try:
                mode = os.stat(path).st_mode
            except OSError:
                continue  # hoppa över otillgängliga filer

            issues = []
            if mode & stat.S_IWOTH:
                issues.append("world-writable")
            if mode & stat.S_ISUID:
                issues.append("setuid")
            if mode & stat.S_ISGID:
                issues.append("setgid")

            if issues:
                findings.append({
                    "path": path,
                    "mode": stat.filemode(mode),
                    "issues": issues,
                })

    return findings


